# SPDX-License-Identifier: MIT
# The board's Arduino connector as machine sees it, and the hardware behind it: Pin on Linux GPIO
# lines, ADC, PWM and I2C on the Cortex-M4 (mpy_m4). In the LVGL MPY Studio simulator there is no
# hardware: a stand-in gives changing values, so the screen can be tried without a board.

import time

try:
    import machine
    import mpy_m4

    HARDWARE = mpy_m4.available() and hasattr(machine, "PWM")
except ImportError:
    machine = mpy_m4 = None
    HARDWARE = False

# name, MCU pin, kind: gpio (a Linux GPIO line), adc, pwm, i2c, spi, uart (the M4's)
PINS = [
    ("D0", "PE7", "uart"), ("D1", "PE8", "uart"), ("D2", "PE1", "gpio"), ("D3", "PD14", "gpio"),
    ("D4", "PE10", "gpio"), ("D5", "PD15", "gpio"), ("D6", "PE9", "pwm"), ("D7", "PD1", "gpio"),
    ("D8", "PG3", "gpio"), ("D9", "PH6", "gpio"), ("D10", "PE11", "gpio"), ("D11", "PE14", "spi"),
    ("D12", "PE13", "spi"), ("D13", "PE12", "spi"), ("D14", "PA12", "i2c"), ("D15", "PA11", "i2c"),
    ("A0", "ANA0", "adc"), ("A1", "ANA1", "adc"), ("A2", "PF14", "adc"), ("A3", "PF13", "adc"),
    ("A4", "PC3", "adc"), ("A5", "PF12", "adc"),
]

DESCRIPTIONS = {
    "gpio": "A Linux GPIO line: machine.Pin",
    "adc": "Analog input, 0 to 2.5 V: machine.ADC on the Cortex-M4",
    "pwm": "TIM1 channel 1: machine.PWM on the Cortex-M4",
    "i2c": "I2C5: machine.I2C(5) on the Cortex-M4",
    "spi": "SPI4: machine.SPI(4) on the Cortex-M4",
    "uart": "UART7: machine.UART(7) on the Cortex-M4",
}


def firmware():
    if not HARDWARE:
        return "simulator: values are made up"
    try:
        return mpy_m4.info()
    except OSError as error:
        return "Cortex-M4: %s" % error


class Hardware:
    # What the screen asks of the board; the same calls in the simulator's stand-in below.

    def __init__(self):
        self._pins = {}  # MCU pin -> (machine.Pin, "in" or "out")
        self._pwm = None
        self._adcs = {}
        self._leds = {}

    def release(self, pin):
        old = self._pins.pop(pin, None)
        if old is not None:
            old[0].deinit()
        if pin == "PE9" and self._pwm is not None:
            self._pwm.deinit()
            self._pwm = None

    def pin_in(self, pin, pull_up):
        self.release(pin)
        pull = machine.Pin.PULL_UP if pull_up else None
        self._pins[pin] = (machine.Pin(pin, machine.Pin.IN, pull), "in")

    def pin_out(self, pin, value):
        if pin in self._pins and self._pins[pin][1] == "out":
            self._pins[pin][0].value(value)
            return
        self.release(pin)
        self._pins[pin] = (machine.Pin(pin, machine.Pin.OUT, value=value), "out")

    def pin_value(self, pin):
        return self._pins[pin][0].value()

    def seen_by_m4(self, pin):
        # The level the Cortex-M4 reads on the pin, whoever drives it.
        frequency, high = mpy_m4.measure(pin, 2)
        return 1 if high > 0.5 else 0

    def adc_uv(self, pin):
        if pin not in self._adcs:
            self._adcs[pin] = machine.ADC(pin)
        return self._adcs[pin].read_uv()

    def pwm(self, frequency, percent):
        duty = percent * 65535 // 100
        if self._pwm is None:
            self._pwm = machine.PWM("PE9", freq=frequency, duty_u16=duty)
        else:
            self._pwm.init(freq=frequency, duty_u16=duty)

    def measure(self, pin, frequency):
        # A few periods of the signal, at least 10 ms.
        return mpy_m4.measure(pin, max(10, min(1000, 3000 // frequency + 1)))

    def scan(self):
        return machine.I2C(5).scan()

    def led(self, name, on):
        if name == "orange":  # PH7, which the device tree gives the Cortex-M4
            mpy_m4.led(on)
        elif name == "blue":
            # PD11 belongs to Linux's LED class as "heartbeat": on is steady, off gives the
            # blinking back to the kernel.
            root = "/sys/class/leds/heartbeat/"
            with open(root + "trigger", "w") as f:
                f.write("none" if on else "heartbeat")
            if on:
                with open(root + "brightness", "w") as f:
                    f.write("1")
        else:
            # PA13, active low. (PA14, the green LED, is also the USER1 button, whose interrupt the
            # device tree gives the M4: Linux may read it but not drive it.)
            if "PA13" not in self._leds:
                self._leds["PA13"] = machine.Pin("PA13", machine.Pin.OUT, value=1)
            self._leds["PA13"].value(0 if on else 1)


class Simulated:
    # The simulator's stand-in: an output reads back what was set, inputs and ADCs change slowly.

    def __init__(self):
        self._out = {}
        self._pwm = (1000, 25)

    def release(self, pin):
        self._out.pop(pin, None)

    def pin_in(self, pin, pull_up):
        self._out.pop(pin, None)

    def pin_out(self, pin, value):
        self._out[pin] = value

    def pin_value(self, pin):
        if pin in self._out:
            return self._out[pin]
        return (time.ticks_ms() // 1000 + len(pin)) % 2

    def seen_by_m4(self, pin):
        return self.pin_value(pin)

    def adc_uv(self, pin):
        phase = (time.ticks_ms() // 50 + 37 * len(pin) + ord(pin[-1])) % 200
        return 400000 + abs(phase - 100) * 15000

    def pwm(self, frequency, percent):
        self._pwm = (frequency, percent)

    def measure(self, pin, frequency):
        return float(self._pwm[0]), self._pwm[1] / 100

    def scan(self):
        return [0x3C, 0x76]

    def led(self, name, on):
        pass


hardware = Hardware() if HARDWARE else Simulated()
